import { Drawer, message, Modal } from 'antd'
import requestService from 'api/request'
import { clsx } from 'clsx'
import { formatNumber } from 'lib/helpers'
import React, { useState } from 'react'
import { useTranslation } from 'react-i18next'
import { useAuthApp } from 'store/useAuthApp'
import { useGlobalAppStore } from 'store/useGlobalApp'
import { useCopyToClipboard } from "@uidotdev/usehooks";
import Countdown from 'react-countdown'
import { AddPaymentMethod } from './AddPaymentMethod'

interface Props {
    setOpen: (val: boolean) => void,
    open: boolean
}
const Withdraw = ({ setOpen, open }: Props) => {
    const { t } = useTranslation()
    const { user } = useAuthApp()
    const { configApp } = useGlobalAppStore()
    const [paymentMethod, setPaymentMethod] = useState('crypto')
    const [openAddMethod, setAddMethod] = useState(false)
    const [_, copyToClipboard] = useCopyToClipboard();
    const [amount, setAmount] = useState(0)
    const [resultDeposit, seResultDeposit] = useState<any>(null)

    const reset = () => {
        // setAddMethod(false)
        setAmount(0)
        setPaymentMethod('crypto')
        seResultDeposit(null)
    }

    const handleDeposit = async () => {
        try {
            const res = await requestService.post('/profile/deposit', {
                data: {
                    amount,
                    fiatAmount: amount * configApp?.rateUsd,
                    paymentMethod,
                    note: "MP" + Date.now(),
                }
            })
            if (res && res.data) {
                setAddMethod(true)
                seResultDeposit(res.data?.data)
            }
        } catch (error) {
            console.log('====================================');
            console.log(error);
            console.log('====================================');
        }
    }
    return (
        <>
            <AddPaymentMethod
                open={openAddMethod}
                setOpen={setAddMethod}
            />
            <Drawer
                title={
                    <div className='text-center'>
                        {t("home.withdraw")}
                    </div>
                }
                placement={'right'}
                closable={true}
                closeIcon={
                    <div>
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="size-5 hover:text-[#000]">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5 8.25 12l7.5-7.5" />
                        </svg>


                    </div>
                }
                onClose={() => {
                    reset()
                    setOpen(false)
                }}
                width="100VW"
                open={open}

            >
                <div data-v-0fbd6467="" className="balance-card">
                    <div data-v-0fbd6467="" className="label">
                        Số dư có thể rút
                    </div>
                    <div data-v-0fbd6467="" className="amount">
                        <span data-v-0fbd6467="" className="value">
                            {user?.realBalance?.toLocaleString()}
                        </span>
                        <span data-v-0fbd6467="" className="currency">
                            $
                        </span>
                    </div>
                </div>
                <div data-v-7d13b5f8="" className="amount-section">
                    <div data-v-7d13b5f8="" className="section-title">
                        Withdraw amount
                    </div>
                    <div data-v-7d13b5f8="" className="van-cell van-field">
                        {/**/}
                        {/**/}
                        <div className="van-cell__value van-field__value">
                            <div className="van-field__body gap-2">
                                <input
                                    type="text"
                                    inputMode="decimal"
                                    id="van-field-17-input"
                                    className="van-field__control van-field__control--right 
                                    !placeholder:text-[#dddd]
                                    "
                                    placeholder="0"
                                    data-allow-mismatch="attribute"
                                />
                                {/**/}
                                <div className="van-field__right-icon">
                                    <div data-v-7d13b5f8="" className="right-content">

                                        <button
                                            data-v-7d13b5f8=""
                                            type="button"
                                            className="van-button van-button--default van-button--small"
                                        >
                                            <div className="van-button__content">
                                                {/**/}
                                                <span className="van-button__text">All</span>
                                                {/**/}
                                            </div>
                                        </button>
                                    </div>
                                </div>
                                {/**/}
                            </div>
                            {/**/}
                            {/**/}
                        </div>
                        {/**/}
                        {/**/}
                    </div>
                </div>
                <div data-v-7d13b5f8="" className="channel-section">
                    <div data-v-7d13b5f8="" className="section-title">
                        <span data-v-7d13b5f8="">Select Bank Account</span>
                        <button
                            data-v-7d13b5f8=""
                            type="button"
                            onClick={() => {
                                setOpen(false)
                                setTimeout(() => (
                                    setAddMethod(true)
                                ), 150)


                            }}
                            className="van-button van-button--primary van-button--small justify-end van-button--plain add-btn"
                        >
                            <div className="van-button__content">
                                {/**/}
                                <span className="van-button__text">Add Bank</span>
                                {/**/}
                            </div>
                        </button>
                    </div>
                    <div data-v-7d13b5f8="" className="channel-list" />
                </div>
                <div data-v-7d13b5f8="" className="submit-section">
                    <button
                        data-v-7d13b5f8=""
                        type="button"
                        className="w-full text-[#fff] van-button van-button--primary van-button--normal van-button--block"
                    >
                        <div className="van-button__content">
                            {/**/}
                            <span className="van-button__text">Confirm withdrawal</span>
                            {/**/}
                        </div>
                    </button>
                </div>

                <div data-v-7d13b5f8="" className="notice-section">
                    <div data-v-7d13b5f8="" className="section-title">
                        Withdrawal instructions
                    </div>
                    <div data-v-7d13b5f8="" className="notice-content">
                        1. Số tiền rút tối thiểu: 54000 ₫<br />
                        2. Thời gian đón hàng ngày: 10 giờ sáng đến 5 giờ chiều
                        <br />
                        3. Phí rút: 6%
                        <br />
                        Giới hạn rút USDT: 50,6USDT-10.000USDT (chỉ hỗ trợ mạng TRC20)
                        <br />
                        Mẹo ngân hàng: Trước khi rút tiền, hãy kiểm tra kỹ thông tin tài khoản ngân
                        hàng và loại VNĐ của bạn để đảm bảo tiền rút của bạn đến nơi nhanh chóng.
                        (Nếu số tiền rút bị trả lại do tài khoản bất thường, vui lòng thay đổi/thêm
                        tài khoản rút tiền và gửi lại)
                    </div>
                </div>


            </Drawer>

        </>
    )
}


export default Withdraw
